#!/usr/bin/env python3
"""
agent-078 -- n=7 size-optimal DAG, commutation classes by DEPTH, and an
independently-verified size-16 depth-6 7-sorter (size/depth tradeoff at n=7).

Runs bfs(n=7, fix_first) with level retention, builds the size-optimal-path DAG,
then enumerates Foata (layer) normal forms over that DAG and buckets them by
number of layers = DEPTH.  Emits the lexicographically first minimum-depth
example and verifies it two independent ways:
  (V1) all 2^n binary vectors sort  (the model the search uses)
  (V2) all n! permutations of 1..n sort  (a DIFFERENT model -- this is the check
       that the zero-one principle was applied correctly, not an assumption)

SCOPE FLAG, stated in the output: with --fix-first the class COUNTS are counts of
classes whose first comparator is (0,1), not of all classes.  The EXISTENCE claim
(a size-16 depth-6 7-sorter exists) needs no lemma at all -- the witness is
verified directly.
"""
import sys, json, time, argparse
from itertools import combinations, permutations
import importlib.util as _u

_D = __file__.rsplit("/", 1)[0]


def _load(name):
    s = _u.spec_from_file_location(name.split("_")[0], _D + "/" + name)
    m = _u.module_from_spec(s); s.loader.exec_module(m); return m


obfs = _load("agent-078_outputset_bfs_size_optima_20260807T223000Z.py")
cc = _load("agent-078_commutation_classes_20260807T232000Z.py")


def verify_binary(net, n):
    for v in range(1 << n):
        x = [(v >> c) & 1 for c in range(n)]
        for i, j in net:
            if x[i] > x[j]:
                x[i], x[j] = x[j], x[i]
        if any(x[c] > x[c + 1] for c in range(n - 1)):
            return False
    return True


def verify_perms(net, n):
    for p in permutations(range(1, n + 1)):
        x = list(p)
        for i, j in net:
            if x[i] > x[j]:
                x[i], x[j] = x[j], x[i]
        if x != sorted(x):
            return False
    return True


def run(n, fix_first=True, verbose=True):
    t0 = time.time()
    r = obfs.bfs(n, fix_first=fix_first, verbose=verbose, keep_levels=True)
    k = r["min_size"]
    if k is None:
        raise SystemExit("BFS did not reach goal")
    F = r["_levels"]
    comps = obfs.comparators(n)
    goal = obfs.goal_state(n)
    if verbose:
        print("  BFS done S(%d)=%d  %.1fs; backward filter..." % (n, k, time.time() - t0))
    G = [None] * len(F)
    G[-1] = {goal}
    for t in range(len(F) - 2, -1, -1):
        keep = set()
        for s in F[t]:
            for bad, d, _ in comps:
                c = obfs.apply_comp(s, bad, d)
                if c != s and c in G[t + 1]:
                    keep.add(s); break
        G[t] = keep
    F[:] = []
    nodes = [len(x) for x in G]
    if verbose:
        print("  optimal-path DAG nodes per level:", nodes, "total", sum(nodes))
        sys.stdout.flush()
    # layered (Foata) enumeration over the DAG
    cmap = {ij: (bad, d) for bad, d, ij in comps}
    prep = [(len(m), sum((1 << i) | (1 << j) for i, j in m), m)
            for m in cc.matchings(n)]
    off = r["level_offset"]
    prof = {}
    best = [None]
    total = [0]

    def apply_layer(s, m):
        for ij in m:
            bad, d = cmap[ij]
            s = (s & ~bad) | ((s & bad) << d)
        return s

    def rec(t, s, prev_mask, layers):
        if t == k:
            if s == goal:
                total[0] += 1
                dep = len(layers) + (1 if fix_first else 0)
                prof[dep] = prof.get(dep, 0) + 1
                if best[0] is None or dep < best[0][0]:
                    pre = [[(0, 1)]] if fix_first else []
                    best[0] = (dep, [list(L) for L in pre + list(layers)])
            return
        for sz, mask, m in prep:
            if t + sz > k:
                continue
            if prev_mask is not None:
                bad_layer = False
                for i, j in m:
                    if not ((1 << i) | (1 << j)) & prev_mask:
                        bad_layer = True; break
                if bad_layer:
                    continue
            ns = apply_layer(s, m)
            if ns in G[t + sz - off + off]:   # index == comparators used so far
                layers.append(m)
                rec(t + sz, ns, mask, layers)
                layers.pop()

    if fix_first:
        s1 = list(G[0])[0]
        rec(1, s1, (1 << 0) | (1 << 1), [])
    else:
        rec(0, obfs.start_state(n), None, [])

    out = {"n": n, "min_size": k, "fix_first": fix_first,
           "dag_nodes_per_level": nodes, "dag_node_count": sum(nodes),
           "commutation_classes": total[0],
           "classes_by_depth": dict(sorted(prof.items())),
           "wall_seconds": round(time.time() - t0, 2)}
    if best[0]:
        dep, layers = best[0]
        net = [tuple(c) for L in layers for c in L]
        out["min_depth_witness"] = {
            "depth": dep, "size": len(net),
            "layers": [[list(c) for c in L] for L in layers],
            "sequence": [list(c) for c in net],
            "verify_all_2^n_binary_vectors": verify_binary(net, n),
            "verify_all_n!_permutations": verify_perms(net, n)}
    out["scope_note"] = (
        "with fix_first=True the class COUNTS are restricted to networks whose "
        "first comparator is (0,1); the min_depth_witness existence claim is "
        "unconditional because the witness is verified directly in two models.")
    return out


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--n", type=int, default=7)
    ap.add_argument("--no-fix-first", action="store_true")
    ap.add_argument("--json")
    a = ap.parse_args()
    r = run(a.n, fix_first=not a.no_fix_first)
    print(json.dumps(r, indent=2))
    if a.json:
        json.dump(r, open(a.json, "w"), indent=2)
